// Design Atlas v3 modules: original, dependency-free components with motion. Register here; engine merges them.
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const def=(id,name,category,description,mood,props,tags,fields={})=>({id,name,category,description,mood,props,tags,fields});
const rows=(v,max=20)=>String(v||'').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,max).map(s=>s.split('|').map(x=>esc(x.trim())));
const list=v=>String(v||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,12).map(esc);
const br=v=>esc(v).replaceAll('\n','<br>');
const head=(p,cls='')=>`<header class="section-heading ${cls}"><span class="eyebrow">${esc(p.eyebrow)}</span><h2>${br(p.title)}</h2><p>${esc(p.subtitle)}</p></header>`;
const btn=(t,secondary=false)=>t?`<button type="button" class="btn${secondary?' secondary':''}" data-demo>${esc(t)}${secondary?'':' <span aria-hidden="true">↗</span>'}</button>`:'';
const acts=p=>`<div class="actions">${btn(p.button)}${btn(p.secondary,true)}</div>`;
const id=b=>esc(String(b.uid).replace(/[^\w-]/g,''));

