const R={
 'hero-gradient':p=>`<div class="hg-glow" aria-hidden="true"><i></i><i></i><i></i></div><div class="hg-inner"><span class="hg-badge"><b aria-hidden="true">✦</b>${esc(p.eyebrow)}</span><h1 class="fx-title hg-title">${br(p.title)}</h1><p class="hg-sub">${esc(p.subtitle)}</p>${acts(p)}<ul class="hg-pills" aria-label="主要能力">${rows(p.items,8).map((x,i)=>`<li style="--i:${i}">${x[0]}</li>`).join('')}</ul></div>`,
 'hero-glass':p=>`<div class="glass-blobs" aria-hidden="true"><i></i><i></i><i></i></div><div class="glass-copy">${head(p)}${acts(p)}</div><div class="glass-stack">${rows(p.items,4).map((x,i)=>`<article class="glass-card fx-card" style="--i:${i}"><small>${x[0]}</small><strong>${x[1]||''}</strong><span>${x[2]||''}</span><i aria-hidden="true"></i></article>`).join('')}</div>`,
 'hero-terminal':(p,b)=>`<div class="term-copy">${head(p)}${acts(p)}</div><div class="terminal fx-card" role="img" aria-label="终端命令演示"><div class="terminal-bar"><i></i><i></i><i></i><span>~/my-site — zsh</span></div><pre class="terminal-body" data-terminal="${id(b)}">${rows(p.items,6).map(x=>`<span class="t-line"><b>$</b> <span class="t-cmd" data-type="${x[0]}">${x[0]}</span></span><span class="t-out">${x[1]||''}</span>`).join('')}<span class="t-line"><b>$</b> <span class="t-caret"></span></span></pre></div>`,
 'hero-stack':p=>`<div class="stack-copy">${head(p)}${acts(p)}</div><div class="stack-cards" aria-hidden="true">${rows(p.items,3).map((x,i)=>`<div class="stack-card fx-tilt sc-${i}"><small>${x[0]} · 0${i+1}</small><span>${x[2]||'✳'}</span><b>${x[1]||''}</b></div>`).join('')}</div>`,
 'logo-cloud':p=>{const r=rows(p.items,16),line=(list,rev)=>`<div class="logo-row${rev?' rev':''}"><div>${[...list,...list].map((x,i)=>`<span ${i>=list.length?'aria-hidden="true"':''}><b aria-hidden="true">${x[1]||'◆'}</b>${x[0]}</span>`).join('')}</div></div>`;return `<div class="center">${head(p)}</div>${line(r,false)}${line([...r].reverse(),true)}`},
 'counter-stats':p=>`${head(p)}<div class="counter-grid">${rows(p.items,6).map(x=>{const n=parseFloat(String(x[0]).replace(/[^\d.]/g,''))||0;return `<div class="counter"><strong><span data-count-to="${n}" data-decimals="${(String(x[0]).split('.')[1]||'').length}">${x[0]}</span><small>${x[1]||''}</small></strong><span>${x[2]||''}</span></div>`}).join('')}</div>`,
 'team-grid':p=>`${head(p)}<div class="team-grid">${rows(p.items,8).map((x,i)=>`<article class="member fx-card" tabindex="0"><div class="member-avatar" style="--h:${(i*67+150)%360}" aria-hidden="true">${esc(String(x[0]).replace(/&[^;]+;/g,'').split(/\s+/).map(w=>w[0]||'').join('').slice(0,2))}</div><h3>${x[0]}</h3><small>${x[1]||''}</small><p>${x[2]||''}</p></article>`).join('')}</div>`,
 'compare-slider':(p,b)=>`${head(p,'center')}<div class="compare" style="--pos:50%"><div class="compare-pane before" aria-hidden="true"><div class="cmp-ui old"><i></i><i></i><i></i><b></b><b></b><b></b><b></b><span></span></div><em>${esc(p.button)}</em></div><div class="compare-pane after" aria-hidden="true"><div class="cmp-ui new"><i></i><b></b><b></b><span></span></div><em>${esc(p.secondary)}</em></div><span class="compare-handle" aria-hidden="true">⟷</span><label class="sr-only" for="cmp-${id(b)}">对比位置</label><input id="cmp-${id(b)}" type="range" min="0" max="100" value="50" data-compare></div>`,
 'accordion-panels':p=>`${head(p)}<div class="accordion-row">${rows(p.items,6).map((x,i)=>`<button type="button" class="acc-panel fx-card" data-acc aria-expanded="${i===0}"><span class="acc-glyph" aria-hidden="true">${x[3]||'✳'}</span><small>0${i+1} · ${x[0]}</small><b>${x[1]||''}</b><span class="acc-text">${x[2]||''}</span></button>`).join('')}</div>`,
 'carousel':p=>{const r=rows(p.items,8);return `<div class="center">${head(p)}</div><div class="carousel" data-carousel data-index="0" aria-roledescription="轮播"><div class="carousel-track">${r.map((x,i)=>`<figure class="carousel-slide" aria-label="${i+1} / ${r.length}"><blockquote>“${x[0]}”</blockquote><figcaption><span class="avatar">${(x[1]||'?').slice(0,1)}</span><b>${x[1]||''}</b><small>${x[2]||''} · 演示</small></figcaption></figure>`).join('')}</div><div class="carousel-nav"><button type="button" data-carousel-step="-1" aria-label="上一条">←</button><span class="carousel-dots">${r.map((_,i)=>`<button type="button" data-carousel-go="${i}" aria-label="第 ${i+1} 条" aria-current="${i===0}"></button>`).join('')}</span><button type="button" data-carousel-step="1" aria-label="下一条">→</button></div></div>`},
 'feature-zigzag':p=>`${head(p)}<div class="zigzag">${rows(p.items,6).map((x,i)=>`<article class="zz-row"><div class="zz-art zz-${i%3}" aria-hidden="true"><span>${['◈','✳','↗'][i%3]}</span><i></i><i></i><i></i></div><div class="zz-copy"><span class="tag">${x[2]||''}</span><h3>${x[0]}</h3><p>${x[1]||''}</p></div></article>`).join('')}</div>`,
 'sticky-stack':p=>`${head(p)}<div class="sticky-stack">${rows(p.items,6).map((x,i)=>`<article class="stack-item fx-card" style="--i:${i}"><span class="stack-no">${x[2]||String(i+1).padStart(2,'0')}</span><div><h3>${x[0]}</h3><p>${x[1]||''}</p></div></article>`).join('')}</div>`,
 'tilt-cards':p=>`${head(p,'center')}<div class="tilt-grid">${rows(p.items,6).map(x=>`<article class="tilt-card fx-tilt fx-card"><span class="glyph">${x[2]||'✳'}</span><h3>${x[0]}</h3><p>${x[1]||''}</p></article>`).join('')}</div>`,
 'chat-demo':(p,b)=>`<div class="chat-copy">${head(p)}</div><div class="chat panel" data-chat><div class="chat-top"><span class="chat-dot" aria-hidden="true">✳</span><b>Atlas 助手</b><small>本地演示</small></div><div class="chat-log" role="log" aria-live="polite">${rows(p.items,12).map(x=>`<div class="msg ${x[0]==='user'?'me':''}">${x[1]||x[0]}</div>`).join('')}</div><form class="chat-form" data-chat-form><label class="sr-only" for="chat-${id(b)}">输入消息</label><input id="chat-${id(b)}" name="msg" autocomplete="off" maxlength="200" placeholder="说点什么…"><button class="btn">${esc(p.button)}</button></form></div>`,
 'booking-calendar':p=>{const d=new Date(),y=d.getFullYear(),m=d.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),today=d.getDate();return `<div>${head(p)}</div><div class="booking panel" data-booking><div class="booking-head"><b>${y} 年 ${m+1} 月</b><small>选择日期</small></div><div class="cal" role="group" aria-label="选择日期">${['日','一','二','三','四','五','六'].map(x=>`<small>${x}</small>`).join('')}${'<i></i>'.repeat(first)}${Array.from({length:days},(_,i)=>`<button type="button" data-day="${i+1}" ${i+1<today?'disabled':''} aria-pressed="false">${i+1}</button>`).join('')}</div><div class="slots" role="group" aria-label="选择时段">${rows(p.items,8).map(x=>`<button type="button" data-slot="${x[0]}" aria-pressed="false">${x[0]}</button>`).join('')}</div><button type="button" class="btn booking-confirm" data-booking-confirm>${esc(p.button)} ↗</button><p class="tiny booking-note" data-booking-note>请选择日期与时段。</p></div>`},
 'blog-cards':p=>`${head(p)}<div class="blog-grid">${rows(p.items,9).map((x,i)=>`<article class="blog-card fx-card"><div class="blog-cover bc-${i%4}" aria-hidden="true"><span>${['Aa','✳','◐','↗'][i%4]}</span></div><div class="blog-meta"><span>${x[1]||''}</span><time>${x[0]}</time></div><h3>${x[2]||''}</h3><p>${x[3]||''}</p><small>${x[4]||''} 阅读 →</small></article>`).join('')}</div>`,
 'cta-glow':p=>`<div class="glow-card"><div class="glow-inner center">${head(p)}${acts(p)}</div></div>`,
 'footer-giant':p=>`<div class="fg-top"><div><p class="fg-tag">${esc(p.subtitle)}</p><a class="fg-mail" href="mailto:${esc(p.button)}">${esc(p.button)} ↗</a></div>${rows(p.items,4).map(x=>`<nav aria-label="${x[0]}"><h4>${x[0]}</h4>${String(x[1]||'').split(',').filter(Boolean).slice(0,8).map(l=>`<a href="#top" data-nav-link>${l.trim()}</a>`).join('')}</nav>`).join('')}</div><div class="fg-word fx-title" aria-label="${esc(p.title)}">${esc(p.title)}</div><div class="fg-bottom"><small>© ${new Date().getFullYear()} ${esc(p.title)} · 原创演示 MIT</small><a href="#top" data-nav-link>回到顶部 ↑</a></div>`,
 'countdown':p=>`<div class="center">${head(p)}<div class="countdown" data-countdown="${esc(p.secondary)}" role="timer" aria-label="距离 ${esc(p.secondary)}">${[['days','天'],['hours','时'],['minutes','分'],['seconds','秒']].map(([k,l])=>`<div class="cd-unit fx-card"><b data-cd="${k}">--</b><small>${l}</small></div>`).join('')}</div>${btn(p.button)}<small class="tiny">${esc(p.secondary).replace('T',' ')}</small></div>`,
 'music-player':p=>{const r=rows(p.items,8);return `<div class="player panel" data-player data-track="0"><div class="player-art" aria-hidden="true"><span>♪</span><div class="eq">${'<i></i>'.repeat(14)}</div></div><div class="player-body"><span class="eyebrow">${esc(p.eyebrow)}</span><h3 class="fx-title">${esc(p.title)}</h3><p>${esc(p.subtitle)}</p><div class="player-track"><b data-track-name>${r[0]?.[0]||''}</b><small data-track-time>${r[0]?.[1]||''}</small></div><div class="player-bar"><i></i></div><div class="player-controls"><button type="button" data-player-step="-1" aria-label="上一首">⏮</button><button type="button" class="play" data-player-toggle aria-pressed="false" aria-label="播放">▶</button><button type="button" data-player-step="1" aria-label="下一首">⏭</button></div><ol class="player-list">${r.map((x,i)=>`<li data-track-item="${i}" data-name="${x[0]}" data-time="${x[1]||''}" class="${i===0?'on':''}"><span>${x[0]}</span><small>${x[1]||''}</small></li>`).join('')}</ol><small class="tiny">界面演示 · 不播放任何音频</small></div></div>`},
 'scroll-text':p=>`<span class="eyebrow">${esc(p.eyebrow)}</span><p class="scroll-text fx-title" data-scroll-text>${[...String(p.title||'')].slice(0,600).map(c=>/\s/.test(c)?' ':`<span>${esc(c)}</span>`).join('')}</p>`,
 'orbit-icons':p=>{const r=rows(p.items,10);return `<div class="orbit-copy">${head(p)}</div><div class="orbit-wrap" aria-hidden="true"><div class="orbit-core">✳</div><div class="orbit o1">${r.slice(0,Math.ceil(r.length/2)).map((x,i,a)=>`<span style="--a:${(360/a.length)*i}deg">${x[0]}</span>`).join('')}</div><div class="orbit o2">${r.slice(Math.ceil(r.length/2)).map((x,i,a)=>`<span style="--a:${(360/a.length)*i+20}deg">${x[0]}</span>`).join('')}</div></div><ul class="sr-only">${r.map(x=>`<li>${x[0]}</li>`).join('')}</ul>`}
};
export function renderFx(b){const fn=R[b.type];return fn?fn(b.props,b):null;}

